mapper.update:
UPDATE SYT0MG
   SET TR_CO_CD        = #{trCoCd, jdbcType=VARCHAR}
     , TRUSTEE         = #{trustee, jdbcType=VARCHAR}
     , JM_CD           = #{yjCd, jdbcType=VARCHAR}
     , BS_TYPE         = NVL(#{bsType, jdbcType=NUMERIC}, 0)
     , CURRENCY        = #{currency, jdbcType=VARCHAR}
     , TR_JUSU         = NVL(#{trJusu, jdbcType=NUMERIC}, 0)
     , TR_DANGA        = NVL(#{trDanga, jdbcType=NUMERIC}, 0)
     , TR_TAX          = NVL(#{trTax, jdbcType=NUMERIC}, 0)
     , TR_COST         = NVL(#{trCost, jdbcType=NUMERIC}, 0)
     , TR_AEK          = NVL(#{trAek, jdbcType=NUMERIC}, 0)
     , GYULJE_YMD      = TO_DATE(REPLACE(#{gyuljeYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
     , GYULJE_AEK      = NVL(#{gyuljeAek, jdbcType=NUMERIC}, 0)
     , GYULJE_JM_CD    = #{gyuljeJmCd, jdbcType=VARCHAR}
     , COUNT_COST      = #{countCost, jdbcType=VARCHAR}
     , SEC_CODE        = #{secCode, jdbcType=VARCHAR}
     , SETT_LOCATION   = #{settLocation, jdbcType=VARCHAR}
     , COUNT_BIC       = #{countBic, jdbcType=VARCHAR}
     , TRANS_RT        = #{transRt, jdbcType=NUMERIC}
     , WON_GYULJE_AEK  = #{wonGyuljeAek, jdbcType=NUMERIC}
     , FCUR_GYULJE_AEK = #{fcurGyuljeAek, jdbcType=NUMERIC}
 WHERE CORP_GR = #{corpGr, jdbcType=VARCHAR}
   AND TR_YMD  = TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_CD   = #{trCd, jdbcType=VARCHAR}
   AND FUND_CD = #{fundCd, jdbcType=VARCHAR}
   AND TR_SEQ  = #{trSeq, jdbcType=NUMERIC}

